/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: TitleProposalFlag, ProposalCell, TitleProposalRow, TitleProposal
 *   Functions: titleProposal, titleCleanup, withTitleProposal, proposalCells, titleDefaults, reviewEditor,
 *              cleanupState, toggleCleanup
 * Internal
 *   Types: NumberField, SourceTrack, DraftTrack
 *   Functions: blocking, titleEdit, cleanable
 *   Constants: paddedDiscTrack
 * @end-catalog */

/**
 * The Disc and Track Numbers an existing-Album review proposes from the track titles it captured, and the optional removal of
 * those positions from the draft titles (owner rules: docs/business-rules.md, Catalog Visibility and Administration, the proposal
 * on open and its cleanup step). Positions are read as the server's Track-title lookup reads them (titleLeadingPosition in
 * reviewLookupStatus.ts, kept in parity with src/administration/lookup/lookupTitlePositions.ts), always from the captured titles,
 * so a saved cleaned title never removes its own proposal. The guard is the server's all-or-nothing leadingTitlePositions plus
 * the review's own checks (a saved number that disagrees, several discs without a captured Disc Number); unlike the server, it
 * names each row that stops it. Pure: the page derives it on every render and never stores it.
 */
import type { CatalogReview, ReviewDraft } from './catalogReviewApi';
import type { ProposedValues } from './catalogReviewApplyModel';
import { withEdits, type ReviewEdits } from './catalogReviewEdits';
import { titleLeadingPosition, type TitleLeadingPosition } from './reviewLookupStatus';

/** The member numbers a title position gives. */
type NumberField = 'discNumber' | 'trackNumber';
/** A captured source track: an absent Disc Number was not captured, null means the Track stored none. */
type SourceTrack = { slotId: string; title: string; discNumber?: number | null; trackNumber: number | null };
/** A draft track's title and numbers, saved or as the editor holds them. */
type DraftTrack = { slotId: string; title: string; discNumber: number | null; trackNumber: number | null };

/**
 * Why a row stops the proposal, or (`gap` only) a note that does not: no position (`1999 X`, `Disc2-03`, a title without a
 * number), a position of the other form than most rows, a position at or before the previous row's, one an earlier row already
 * has, a saved number of its member that differs, a Disc Number the review never captured on an Album whose titles name several
 * discs, a lone member's position that is not a Disc and zero-padded Track Number (`7 Rings`, `1-2 Punch`), and a track number
 * more than one past the highest earlier one on its disc.
 */
export type TitleProposalFlag = 'noPosition' | 'formMismatch' | 'notIncreasing' | 'duplicate' | 'disagrees' | 'discNotCaptured' | 'loneTrackOnly' | 'gap';
/**
 * A number cell compared with the catalog's stored value: filling an empty one, equal to it as the title gives it, kept as stored,
 * replacing a stored value with another or none, or empty on both sides.
 */
export type ProposalCell = 'fill' | 'same' | 'keep' | 'overwrite' | 'none';
/** One member's reading: its captured title and position, the flags it raises and the empty saved numbers the proposal fills. */
export type TitleProposalRow = { slotId: string; title: string; position: TitleLeadingPosition | null; flags: TitleProposalFlag[];
  proposed: Partial<Record<NumberField, number>> };
/**
 * The Album's proposal: the form most positions take (a Disc and Track Number, a Track Number alone, or none read), whether the
 * guard accepts it (no row raises a flag other than `gap`), each row, how many members get a number, and whether the proposed
 * numbers start selected (only Disc and Track positions do; Track Numbers alone are proposed unselected).
 */
export type TitleProposal = { form: 'discTrack' | 'track' | null; accepted: boolean; rows: TitleProposalRow[]; count: number; preselected: boolean };

/** Every flag but a gap stops the proposal. */
const blocking = (flag: TitleProposalFlag) => flag !== 'gap';
/** A Disc Number, `-` or `.`, and a Track Number written with a leading zero, as a lone member's position must be (the server's paddedDiscTrack). */
const paddedDiscTrack = /^\d{1,2}[-.]0\d/u;

/**
 * The proposal from the captured `source` titles over the `saved` draft's numbers. Only empty saved numbers are proposed, a Disc
 * Number only from a Disc and Track position and only where the review captured one; nothing is proposed unless accepted, so a
 * proposal never makes two members claim one position and never replaces a member's own or lookup-filled number.
 */
export function titleProposal(source: readonly SourceTrack[], saved: readonly DraftTrack[]): TitleProposal {
  const parsed = source.map(track => titleLeadingPosition(track.title)), positioned = parsed.filter(value => value !== null);
  const withDisc = positioned.filter(value => value.discNumber !== null).length, rest = positioned.length - withDisc;
  const form = !positioned.length ? null : withDisc > rest || (withDisc === rest && positioned[0].discNumber !== null) ? 'discTrack' : 'track';
  const discs = new Set(positioned.flatMap(value => value.discNumber === null ? [] : [value.discNumber]));
  const seen = new Set<string>(), highest = new Map<number, number>();
  let previous: [number, number] | null = null;
  const rows = source.map((track, index): TitleProposalRow => {
    const position = parsed[index], draft = saved.find(value => value.slotId === track.slotId), flags: TitleProposalFlag[] = [];
    if (!position) return { slotId: track.slotId, title: track.title, position, flags: ['noPosition'], proposed: {} };
    const disc = position.discNumber ?? 1, at = `${disc}:${position.trackNumber}`;
    if ((position.discNumber !== null) !== (form === 'discTrack')) flags.push('formMismatch');
    if (seen.has(at)) flags.push('duplicate');
    else if (previous && (disc < previous[0] || (disc === previous[0] && position.trackNumber <= previous[1]))) flags.push('notIncreasing');
    if (source.length === 1 && (position.discNumber === null || !paddedDiscTrack.test(track.title.trimStart()))) flags.push('loneTrackOnly');
    if (draft && ((draft.trackNumber !== null && draft.trackNumber !== position.trackNumber)
      || (position.discNumber !== null && draft.discNumber !== null && draft.discNumber !== position.discNumber))) flags.push('disagrees');
    if (position.discNumber !== null && discs.size > 1 && track.discNumber === undefined && (draft?.discNumber ?? null) === null) flags.push('discNotCaptured');
    const top = highest.get(disc);
    if (!flags.length && top !== undefined && position.trackNumber > top + 1) flags.push('gap');
    seen.add(at);
    highest.set(disc, Math.max(top ?? 0, position.trackNumber));
    previous = [disc, position.trackNumber];
    return { slotId: track.slotId, title: track.title, position, flags, proposed: {} };
  });
  const accepted = rows.length > 0 && !rows.some(row => row.flags.some(blocking));
  if (accepted) for (const row of rows) {
    const draft = saved.find(value => value.slotId === row.slotId), captured = source.find(value => value.slotId === row.slotId)!.discNumber !== undefined;
    if (draft?.trackNumber === null) row.proposed.trackNumber = row.position!.trackNumber;
    if (form === 'discTrack' && captured && (draft?.discNumber ?? null) === null) row.proposed.discNumber = row.position!.discNumber!;
  }
  return { form, accepted, rows, count: rows.filter(row => Object.keys(row.proposed).length).length, preselected: accepted && form === 'discTrack' };
}

/**
 * The cleaned draft titles by slot, offered only when the proposal is accepted: each member's title whose current draft title is
 * still the captured one becomes exactly its text after the position (whitespace collapsed, as the server's `rest`); a title the
 * administrator, Luna or lookup changed is never touched.
 */
export function titleCleanup(proposal: TitleProposal, tracks: readonly Pick<DraftTrack, 'slotId' | 'title'>[]): Record<string, string> {
  const cleaned: Record<string, string> = {};
  if (!proposal.accepted) return cleaned;
  for (const row of proposal.rows) {
    const track = tracks.find(value => value.slotId === row.slotId);
    if (track && row.position && track.title === row.title && row.position.rest !== track.title) cleaned[row.slotId] = row.position.rest;
  }
  return cleaned;
}

/**
 * `draft` with the proposal written in: each proposed number where the draft's is still empty and, with `cleanup`, each cleaned
 * title. The page applies the administrator's own edits after this, so a cleared proposal stays cleared.
 */
export function withTitleProposal(draft: ReviewDraft, proposal: TitleProposal, cleanup: boolean): ReviewDraft {
  const titles = cleanup ? titleCleanup(proposal, draft.tracks) : {};
  return { ...draft, tracks: draft.tracks.map(track => {
    const proposed = proposal.rows.find(row => row.slotId === track.slotId)?.proposed ?? {};
    return { ...track, title: titles[track.slotId] ?? track.title, discNumber: track.discNumber ?? proposed.discNumber ?? null, trackNumber: track.trackNumber ?? proposed.trackNumber ?? null };
  }) };
}

/**
 * Each member's Disc and Track Number cell in `resulting` (the draft as it would be saved) against the captured source value; the
 * Disc cell is null where the review never captured one. A stored value equal to what an accepted title gives is `same`.
 */
export function proposalCells(proposal: TitleProposal, source: readonly SourceTrack[], resulting: readonly DraftTrack[]):
  Record<string, { discNumber: ProposalCell | null; trackNumber: ProposalCell }> {
  const cell = (original: number | null, value: number | null, titled: number | null | undefined): ProposalCell =>
    original === null ? value === null ? 'none' : 'fill' : value !== original ? 'overwrite' : titled === original ? 'same' : 'keep';
  return Object.fromEntries(source.map(track => {
    const row = proposal.rows.find(value => value.slotId === track.slotId), draft = resulting.find(value => value.slotId === track.slotId);
    const titled = proposal.accepted ? row?.position : undefined;
    return [track.slotId, { discNumber: track.discNumber === undefined ? null : cell(track.discNumber, draft?.discNumber ?? null, proposal.form === 'discTrack' ? titled?.discNumber : undefined),
      trackNumber: cell(track.trackNumber, draft?.trackNumber ?? null, titled?.trackNumber) }];
  }));
}

/**
 * What the captured titles give the Update selection's defaults (reviewApplyModel's `proposed`), by item key: the numbers an
 * accepted Disc and Track proposal gives every member (a Disc Number only where captured), which start selected wherever they fill
 * an empty stored value; and each member's cleaned title with the numbers it needs to keep its removed position. Two guards accept
 * a proposal. One reads the catalog's stored numbers rather than the `saved` draft's (whose Disc Numbers count only where the
 * review captured none, as the administrator cannot edit those), so saving the proposed numbers or the administrator's own on some
 * members never changes the defaults of the others. The other reads the `saved` draft, as the proposal table does, so a proposal
 * the table shows as included (a stored number that disagreed, corrected and saved) is selected too.
 */
export function titleDefaults(source: readonly SourceTrack[], saved: readonly DraftTrack[]): ProposedValues {
  const numbers = new Map<string, number>(), titles = new Map<string, { title: string; numbers: NumberField[] }>();
  const stored = source.map(track => ({ slotId: track.slotId, title: track.title, trackNumber: track.trackNumber,
    discNumber: track.discNumber !== undefined ? track.discNumber : saved.find(value => value.slotId === track.slotId)?.discNumber ?? null }));
  // Both guards read the same captured titles, so where both accept they give the same positions.
  for (const proposal of [titleProposal(source, stored), titleProposal(source, saved)]) {
    if (!proposal.accepted) continue;
    for (const row of proposal.rows) {
      const position = row.position!, captured = source.find(value => value.slotId === row.slotId)?.discNumber !== undefined;
      const disc = proposal.form === 'discTrack' && captured, key = (field: string) => `track:${row.slotId}:${field}`;
      if (proposal.preselected) {
        numbers.set(key('trackNumber'), position.trackNumber);
        if (disc) numbers.set(key('discNumber'), position.discNumber!);
      }
      titles.set(key('title'), { title: position.rest, numbers: disc ? ['discNumber', 'trackNumber'] : ['trackNumber'] });
    }
  }
  return { numbers, titles };
}

/**
 * What the edit surface shows for the saved draft `base` and the administrator's `edits`: the proposal from the captured titles
 * over the saved numbers, its Update selection defaults, the draft with every proposed number and then the edits written in (each
 * number input shows the draft value, else the proposal), and the proposed numbers by slot.
 */
export function reviewEditor(source: CatalogReview['source'], base: ReviewDraft, edits: ReviewEdits) {
  const proposal = titleProposal(source.tracks, base.tracks);
  return { proposal, proposed: titleDefaults(source.tracks, base.tracks), shown: withEdits(withTitleProposal(base, proposal, false), edits),
    numbers: Object.fromEntries(proposal.rows.map(row => [row.slotId, row.proposed])) };
}

/** A member's title edit set to `title`, or removed (undefined), leaving its other edits. */
const titleEdit = (edits: ReviewEdits, slotId: string, title: string | undefined): ReviewEdits => {
  const { title: _title, ...rest } = edits.tracks?.[slotId] ?? {};
  return { ...edits, tracks: { ...edits.tracks, [slotId]: title === undefined ? rest : { ...rest, title } } };
};
/** The rows whose captured title the cleanup changes, each with the title the draft shows. */
const cleanable = (proposal: TitleProposal, shown: readonly Pick<DraftTrack, 'slotId' | 'title'>[]) => !proposal.accepted ? []
  : proposal.rows.filter(row => row.position && row.position.rest !== row.title).map(row => ({ row, rest: row.position!.rest, title: shown.find(track => track.slotId === row.slotId)?.title }));

/**
 * The optional title cleanup's checkbox: offered while the proposal is accepted and some member's shown title is still its captured
 * title or its cleaned one (titles the administrator wrote otherwise are never the cleanup's), checked once none is still captured.
 */
export function cleanupState(proposal: TitleProposal, shown: readonly Pick<DraftTrack, 'slotId' | 'title'>[]) {
  const rows = cleanable(proposal, shown), offered = rows.some(({ row, rest, title }) => title === row.title || title === rest);
  return { offered, checked: offered && !rows.some(({ row, title }) => title === row.title) };
}

/**
 * Turning the cleanup on or off over the saved draft `base`: on, each title still as captured becomes its cleaned title; off, each
 * cleaned title the cleanup wrote (`cleaned`, the slots it changed, kept by the page across saves) becomes its captured title
 * again; either way as an edit only where it differs from the saved title. A title the administrator wrote is never touched, even
 * when it equals the cleaned text: when no slot the cleanup wrote is known (the page's editor buffer was lost), turning it off
 * restores only saved cleaned titles, never an unsaved edit. Returns the edits, the slots the cleanup now owns and, when turned on,
 * the Track title items it cleaned, which the caller selects (turning the cleanup on chooses them).
 */
export function toggleCleanup(proposal: TitleProposal, base: ReviewDraft, edits: ReviewEdits, on: boolean, cleaned: readonly string[] = []):
  { edits: ReviewEdits; keys: string[]; cleaned: string[] } {
  const rows = cleanable(proposal, withEdits(base, edits).tracks), owned = new Set(cleaned), known = rows.some(({ row }) => owned.has(row.slotId));
  const keys: string[] = [];
  let next = edits;
  for (const { row, rest, title } of rows) {
    if (title !== (on ? row.title : rest)) continue;
    if (!on && !(known ? owned.has(row.slotId) : edits.tracks?.[row.slotId]?.title === undefined)) continue;
    const target = on ? rest : row.title, saved = base.tracks.find(track => track.slotId === row.slotId)?.title;
    next = titleEdit(next, row.slotId, saved === target ? undefined : target);
    if (on) { keys.push(`track:${row.slotId}:title`); owned.add(row.slotId); } else owned.delete(row.slotId);
  }
  return { edits: next, keys, cleaned: [...owned] };
}
